"use client";
import React from "react";
import { motion } from "framer-motion";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="relative w-full max-w-4xl mx-auto px-4">
      <div className="relative flex items-center justify-center" style={{ height: "380px" }}>
        {cards.map((card, index) => {
          // Each card offset horizontally with slight rotation for deck effect
          const baseOffset = index * 60; // 0px, 60px, 120px
          const baseRotate = index * 4; // 0deg, 4deg, 8deg

          return (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 60 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: index * 0.15, ease: [0.25, 0.46, 0.45, 0.94] }}
              whileHover={{
                y: -60,
                rotate: 0,
                transition: { duration: 0.4, ease: "easeOut" }
              }}
              className="absolute cursor-pointer"
              style={{
                x: `${baseOffset}px`,
                rotate: `${baseRotate}deg`,
                zIndex: cards.length - index,
              }}
            >
              {/* Card Container */}
              <div
                className="relative rounded-2xl overflow-hidden"
                style={{
                  width: "280px",
                  background: "linear-gradient(145deg, #1a1510 0%, #0f0a08 100%)",
                  border: "1px solid rgba(212, 175, 55, 0.3)",
                  boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
                }}
              >
                {/* Top accent bar */}
                <div
                  className="absolute top-0 left-0 right-0 h-1"
                  style={{ background: "linear-gradient(90deg, #d4af37, #f4d77a, #d4af37)" }}
                />

                {/* Card Content */}
                <div className="relative z-10 p-5">
                  {/* Icon */}
                  <div
                    className="w-10 h-10 rounded-lg flex items-center justify-center mb-3"
                    style={{
                      background: "rgba(212, 175, 55, 0.15)",
                      color: "#d4af37",
                    }}
                  >
                    {card.icon}
                  </div>

                  {/* Badge */}
                  <div className="mb-2">
                    <span
                      className="inline-block text-xs font-semibold uppercase tracking-wider px-2 py-1 rounded-md"
                      style={{
                        background: "rgba(212, 175, 55, 0.15)",
                        color: "#d4af37",
                      }}
                    >
                      {card.badge}
                    </span>
                  </div>

                  {/* Title */}
                  <h3 className="text-lg font-semibold text-white mb-2" style={{ fontFamily: "Cormorant Garamond, serif" }}>
                    {card.title}
                  </h3>

                  {/* Description */}
                  <p className="text-sm leading-relaxed mb-3" style={{ color: "rgba(255,255,255,0.6)" }}>
                    {card.description}
                  </p>

                  {/* Date */}
                  <p className="text-xs" style={{ color: "rgba(255,255,255,0.4)" }}>
                    {card.date}
                  </p>
                </div>

                {/* Bottom decorative corner */}
                <div
                  className="absolute bottom-0 right-0 w-16 h-16"
                  style={{
                    borderBottom: "2px solid #d4af37",
                    borderRight: "2px solid #d4af37",
                    opacity: 0.2,
                  }}
                />
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default DisplayCards;
